<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>VICE MERIDIAN</title>
<script type="importmap">{"imports":{"three":"./vendor/three.module.min.js"}}</script>
<style>
  * { box-sizing: border-box; user-select: none; }
  html, body {
    margin: 0; width: 100%; height: 100%; overflow: hidden;
    background: #140f1e;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    color: #fff6ec;
  }
  #game-wrap { position: fixed; inset: 0; overflow: hidden; }
  #viewport { position: fixed; inset: 0; width: 100%; height: 100%; display: block; }
  #vignette {
    position: fixed; inset: 0; pointer-events: none; z-index: 2;
    background: radial-gradient(ellipse at 50% 48%, rgba(255,190,120,0.03) 50%, rgba(16,8,24,0.46) 100%);
  }
  #damage-flash {
    position: fixed; inset: 0; pointer-events: none; z-index: 3;
    background: radial-gradient(ellipse at 50% 50%, rgba(255,40,50,0) 40%, rgba(220,24,38,0.55) 100%);
    opacity: 0; transition: opacity 0.14s ease-out;
  }
  #hud {
    position: fixed; inset: 0; pointer-events: none; z-index: 10;
    opacity: 0; transition: opacity 0.25s ease;
  }
  #hud.visible { opacity: 1; }

  /* Top-right cluster: stars, money, weapon, district */
  #hud-top-right {
    position: absolute; top: 18px; right: 24px;
    display: flex; flex-direction: column; align-items: flex-end; gap: 6px;
  }
  #wanted-row {
    display: flex; gap: 6px; padding: 5px 10px;
    background: linear-gradient(135deg, rgba(16,12,26,0.72), rgba(26,16,38,0.55));
    border: 1px solid rgba(255,180,100,0.22);
    border-radius: 6px; backdrop-filter: blur(4px);
    min-height: 30px; align-items: center;
  }
  .star {
    font-size: 20px; line-height: 1;
    color: rgba(255,255,255,0.16);
    text-shadow: 0 1px 4px rgba(0,0,0,0.6);
  }
  .star.active {
    color: #ffcf4d;
    text-shadow: 0 0 10px rgba(255,175,40,0.85), 0 1px 3px rgba(0,0,0,0.8);
  }
  .star.flash-red {
    color: #ff4558;
    text-shadow: 0 0 12px rgba(255,55,75,0.95);
  }
  .star.flash-blue {
    color: #46b5ff;
    text-shadow: 0 0 12px rgba(70,180,255,0.95);
  }
  #money-box {
    font-size: 26px; font-weight: 800; letter-spacing: 0.5px;
    color: #5ef2a5;
    text-shadow: 0 2px 8px rgba(0,0,0,0.85), 0 0 14px rgba(94,242,165,0.35);
    font-variant-numeric: tabular-nums;
  }
  #weapon-box {
    display: flex; align-items: center; gap: 10px;
    padding: 5px 12px; border-radius: 6px;
    background: rgba(14,12,24,0.74);
    border: 1px solid rgba(255,140,90,0.28);
    font-size: 13px; font-weight: 700; letter-spacing: 0.8px; text-transform: uppercase;
  }
  #weapon-name { color: #ffd9b3; }
  #weapon-ammo { color: #ff8c5a; font-variant-numeric: tabular-nums; }
  #district-badge {
    font-size: 12px; font-weight: 700; letter-spacing: 1.8px; text-transform: uppercase;
    color: #8ee8f2; padding: 3px 9px; border-radius: 4px;
    background: rgba(10,16,28,0.64); border: 1px solid rgba(94,230,242,0.28);
    text-shadow: 0 1px 4px rgba(0,0,0,0.8);
  }

  /* Top-center mission objective banner */
  #objective-banner {
    position: absolute; top: 18px; left: 50%; transform: translateX(-50%);
    padding: 8px 22px; border-radius: 6px;
    background: linear-gradient(90deg, rgba(16,12,26,0.2) 0%, rgba(18,14,32,0.84) 16%, rgba(18,14,32,0.84) 84%, rgba(16,12,26,0.2) 100%);
    border-top: 2px solid #ff944d;
    border-bottom: 1px solid rgba(255,148,77,0.3);
    text-align: center; min-width: 320px; max-width: 560px;
    display: none;
  }
  #objective-banner.active { display: block; }
  #objective-tag {
    font-size: 10px; font-weight: 800; letter-spacing: 2.4px; text-transform: uppercase;
    color: #ff9c54; margin-bottom: 2px;
  }
  #objective-text {
    font-size: 16px; font-weight: 700; letter-spacing: 0.4px; color: #fff8f0;
    text-shadow: 0 2px 6px rgba(0,0,0,0.9);
  }

  /* Bottom-left: circular minimap + health/armour bars */
  #hud-bottom-left {
    position: absolute; bottom: 22px; left: 24px;
    display: flex; flex-direction: column; align-items: center; gap: 8px;
  }
  #minimap-frame {
    position: relative; width: 176px; height: 176px; border-radius: 50%;
    padding: 4px;
    background: linear-gradient(145deg, rgba(255,156,92,0.72), rgba(50,210,220,0.62));
    box-shadow: 0 6px 22px rgba(0,0,0,0.68), inset 0 0 12px rgba(0,0,0,0.6);
  }
  #minimap {
    width: 100%; height: 100%; border-radius: 50%; display: block;
    background: #101622;
  }
  #minimap-compass {
    position: absolute; top: -4px; left: 50%; transform: translateX(-50%);
    background: #141022; color: #ffcf6e; font-size: 10px; font-weight: 800;
    padding: 1px 6px; border-radius: 8px; border: 1px solid rgba(255,180,100,0.6);
    letter-spacing: 1px;
  }
  #bars-wrap {
    width: 176px; display: flex; flex-direction: column; gap: 5px;
    background: rgba(12,12,22,0.78); padding: 6px 8px; border-radius: 6px;
    border: 1px solid rgba(255,255,255,0.12);
  }
  .stat-row { display: flex; align-items: center; gap: 7px; }
  .stat-label { font-size: 10px; font-weight: 800; letter-spacing: 1px; width: 22px; color: #d5d0df; }
  .bar-track {
    flex: 1; height: 8px; border-radius: 4px; background: rgba(255,255,255,0.12); overflow: hidden;
  }
  .bar-fill { height: 100%; border-radius: 4px; transition: width 0.15s ease; }
  #health-fill { background: linear-gradient(90deg, #ff4558, #4ce88b); width: 100%; }
  #armour-fill { background: linear-gradient(90deg, #2fb8ff, #6ff2ff); width: 100%; }

  /* Bottom-right: speedometer & vehicle info */
  #speedo-box {
    position: absolute; bottom: 24px; right: 26px;
    display: none; flex-direction: column; align-items: flex-end; gap: 4px;
    background: linear-gradient(140deg, rgba(16,12,28,0.82), rgba(28,16,38,0.7));
    border: 1px solid rgba(255,152,86,0.38);
    border-right: 4px solid #ff8c42;
    border-radius: 8px; padding: 10px 16px; min-width: 176px;
    box-shadow: 0 6px 20px rgba(0,0,0,0.55);
  }
  #speedo-box.active { display: flex; }
  #speedo-car {
    font-size: 11px; font-weight: 800; letter-spacing: 1.6px; text-transform: uppercase;
    color: #5ee6f2;
  }
  #speedo-main { display: flex; align-items: baseline; gap: 8px; }
  #speedo-val {
    font-size: 40px; font-weight: 900; line-height: 1;
    color: #fff6ec; font-variant-numeric: tabular-nums;
    text-shadow: 0 0 14px rgba(255,150,70,0.45);
  }
  #speedo-unit { font-size: 12px; font-weight: 700; color: #ffb982; letter-spacing: 1px; }
  #speedo-gear {
    font-size: 15px; font-weight: 900; color: #161022; background: #ffae52;
    padding: 2px 7px; border-radius: 4px; margin-left: 4px;
  }
  #speedo-rpm-track {
    width: 100%; height: 5px; background: rgba(255,255,255,0.14); border-radius: 3px; overflow: hidden; margin-top: 3px;
  }
  #speedo-rpm-fill {
    height: 100%; width: 40%;
    background: linear-gradient(90deg, #4ae8c6 0%, #ffbf47 65%, #ff3b5c 100%);
  }

  /* Bottom-center: dialogue box with speaker name plate */
  #dialogue-box {
    position: absolute; bottom: 26px; left: 50%; transform: translateX(-50%);
    width: min(560px, calc(100% - 430px));
    background: linear-gradient(180deg, rgba(16,14,28,0.88), rgba(12,10,22,0.92));
    border: 1px solid rgba(255,175,110,0.34);
    border-left: 4px solid #ff8c42;
    border-radius: 6px; padding: 12px 16px 13px;
    box-shadow: 0 8px 26px rgba(0,0,0,0.68);
    display: none;
  }
  #dialogue-box.active { display: block; }
  #dialogue-speaker {
    display: inline-block; font-size: 11px; font-weight: 900; letter-spacing: 1.8px;
    text-transform: uppercase; color: #161022; background: linear-gradient(90deg, #ff9947, #ffd070);
    padding: 2px 9px; border-radius: 3px; margin-bottom: 6px;
  }
  #dialogue-text {
    font-size: 15px; line-height: 1.4; color: #fff8f2;
    text-shadow: 0 1px 3px rgba(0,0,0,0.8);
  }

  /* Center crosshair & interaction prompt */
  #crosshair {
    position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%);
    width: 18px; height: 18px; display: none;
  }
  #crosshair.active { display: block; }
  #crosshair::before, #crosshair::after {
    content: ""; position: absolute; background: rgba(255,244,230,0.85);
    box-shadow: 0 0 4px rgba(0,0,0,0.9);
  }
  #crosshair::before { left: 8px; top: 0; width: 2px; height: 18px; }
  #crosshair::after { top: 8px; left: 0; height: 2px; width: 18px; }

  #prompt-toast {
    position: absolute; bottom: 132px; left: 50%; transform: translateX(-50%);
    background: rgba(14,12,24,0.82); color: #ffe3bc;
    border: 1px solid rgba(255,168,94,0.45); border-radius: 5px;
    padding: 6px 14px; font-size: 13px; font-weight: 700; letter-spacing: 0.6px;
    display: none;
  }
  #prompt-toast.active { display: block; }

  #controls-hint {
    position: absolute; top: 18px; left: 24px;
    font-size: 11px; color: rgba(255,240,224,0.75);
    background: rgba(14,12,24,0.58); border: 1px solid rgba(255,255,255,0.12);
    border-radius: 6px; padding: 6px 10px; line-height: 1.5;
  }
  #controls-hint b { color: #ffba6b; }

  /* Title / Pause / Wasted overlays */
  #overlay {
    position: fixed; inset: 0; z-index: 30;
    display: flex; flex-direction: column; align-items: center; justify-content: center;
    background: radial-gradient(ellipse at 50% 42%, rgba(44,20,46,0.55), rgba(10,8,20,0.88));
    backdrop-filter: blur(5px);
    pointer-events: auto;
  }
  #overlay.hidden { display: none; }
  #title-kicker {
    font-size: 12px; font-weight: 800; letter-spacing: 5px; text-transform: uppercase;
    color: #5ef0f0; margin-bottom: 8px;
  }
  #title-logo {
    font-size: 64px; font-weight: 900; letter-spacing: 5px; margin: 0 0 10px;
    background: linear-gradient(180deg, #fff5d6 0%, #ff9947 52%, #ff4070 100%);
    -webkit-background-clip: text; background-clip: text; color: transparent;
    filter: drop-shadow(0 6px 18px rgba(255,80,100,0.42));
  }
  #title-sub {
    font-size: 15px; color: #eadbf0; max-width: 520px; text-align: center;
    line-height: 1.5; margin-bottom: 26px;
  }
  #play-btn {
    pointer-events: auto; cursor: pointer;
    font-size: 16px; font-weight: 900; letter-spacing: 2.5px; text-transform: uppercase;
    color: #160e20; background: linear-gradient(90deg, #ff9947, #ffcf5c);
    border: none; border-radius: 6px; padding: 14px 36px;
    box-shadow: 0 6px 24px rgba(255,140,66,0.45);
  }
  #play-btn:hover { filter: brightness(1.08); }
  #key-grid {
    margin-top: 24px; display: grid; grid-template-columns: repeat(3, auto);
    gap: 8px 22px; font-size: 12px; color: #d8cee6;
  }
  #key-grid b { color: #ffba6b; }
  #wasted-banner {
    position: fixed; inset: 0; z-index: 25; display: none;
    align-items: center; justify-content: center; flex-direction: column;
    background: rgba(30,6,14,0.62); pointer-events: none;
  }
  #wasted-banner.active { display: flex; }
  #wasted-banner h2 {
    margin: 0; font-size: 58px; letter-spacing: 8px; color: #ff4558;
    text-shadow: 0 4px 20px rgba(0,0,0,0.9);
  }
  #wasted-banner p { margin: 8px 0 0; font-size: 15px; color: #ffe8d8; letter-spacing: 1px; }
  #busted-banner {
    position: fixed; inset: 0; z-index: 25; display: none;
    align-items: center; justify-content: center; flex-direction: column;
    background: rgba(8,16,40,0.6); pointer-events: none;
  }
  #busted-banner.active { display: flex; }
  #busted-banner h2 {
    margin: 0; font-size: 58px; letter-spacing: 8px; color: #46b5ff;
    text-shadow: 0 4px 20px rgba(0,0,0,0.9), 0 0 26px rgba(70,180,255,0.45);
  }
  #busted-banner p { margin: 8px 0 0; font-size: 15px; color: #e2efff; letter-spacing: 1px; }
  .respawn-count { margin-top: 14px !important; font-size: 12px !important; letter-spacing: 3px !important; opacity: 0.8; }

  /* Loading veil shown while the city is generated */
  #loading {
    position: fixed; inset: 0; z-index: 40;
    display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 14px;
    background: linear-gradient(180deg, #1d2d5c 0%, #7d4476 55%, #ff8a4c 100%);
    transition: opacity 0.45s ease;
  }
  #loading.done { opacity: 0; pointer-events: none; }
  #loading-title { font-size: 34px; font-weight: 900; letter-spacing: 8px; color: #fff3df; text-shadow: 0 4px 18px rgba(40,10,40,0.7); }
  #loading-track { width: 240px; height: 4px; border-radius: 2px; background: rgba(255,255,255,0.2); overflow: hidden; }
  #loading-fill { width: 0%; height: 100%; background: linear-gradient(90deg, #ffcf5c, #ff4070); transition: width 0.18s ease-out; }
  #loading-step { font-size: 11px; letter-spacing: 3px; text-transform: uppercase; color: #ffe2c4; }
  #loading-pct { font-size: 12px; font-weight: 800; letter-spacing: 2px; color: #fff3df; font-variant-numeric: tabular-nums; }
  #loading-modules {
    list-style: none; margin: 4px 0 0; padding: 0; display: grid; grid-template-columns: repeat(4, auto);
    gap: 3px 14px; font-size: 10px; letter-spacing: 1.4px; text-transform: uppercase; color: rgba(255,236,214,0.42);
  }
  #loading-modules li.done { color: #ffe2c4; }
  #loading-modules li.done::before { content: "✓ "; color: #5ef2a5; }
  #loading-modules li.active { color: #ffcf5c; }

  /* Hit marker, wanted decay and transient toast */
  #hitmarker {
    position: absolute; top: 50%; left: 50%; width: 26px; height: 26px;
    transform: translate(-50%, -50%) rotate(45deg); opacity: 0; transition: opacity 0.08s linear;
  }
  #hitmarker::before, #hitmarker::after { content: ""; position: absolute; background: #fff; box-shadow: 0 0 4px rgba(0,0,0,0.9); }
  #hitmarker::before { left: 12px; top: 0; width: 2px; height: 26px; clip-path: polygon(0 0,100% 0,100% 35%,0 35%,0 65%,100% 65%,100% 100%,0 100%); }
  #hitmarker::after { top: 12px; left: 0; height: 2px; width: 26px; clip-path: polygon(0 0,35% 0,35% 100%,0 100%,0 0,65% 0,100% 0,100% 100%,65% 100%); }
  #hitmarker.kill::before, #hitmarker.kill::after { background: #ff4558; }
  #wanted-decay { width: 100%; height: 3px; border-radius: 2px; background: rgba(255,255,255,0.12); overflow: hidden; display: none; }
  #wanted-decay.active { display: block; }
  #wanted-decay-fill { height: 100%; width: 100%; background: linear-gradient(90deg, #46b5ff, #ff4558); }
  #mission-toast {
    position: absolute; top: 92px; left: 50%; transform: translateX(-50%);
    font-size: 30px; font-weight: 900; letter-spacing: 6px; color: #ffcf5c;
    text-shadow: 0 4px 18px rgba(0,0,0,0.85), 0 0 22px rgba(255,160,60,0.5);
    opacity: 0; transition: opacity 0.3s ease;
  }
  #mission-toast.active { opacity: 1; }
  #mission-toast.fail { color: #ff4558; }
  #objective-timer { font-size: 13px; font-weight: 800; color: #ffcf5c; letter-spacing: 1px; font-variant-numeric: tabular-nums; }
  #title-hint { margin-top: 14px; font-size: 11px; letter-spacing: 2px; color: rgba(255,230,210,0.66); text-transform: uppercase; }
  #title-credits { position: absolute; bottom: 18px; font-size: 11px; letter-spacing: 1.2px; color: rgba(230,214,240,0.55); }
  #continue-btn {
    pointer-events: auto; cursor: pointer; margin-top: 10px; display: none;
    font-size: 12px; font-weight: 800; letter-spacing: 2px; text-transform: uppercase;
    color: #ffd9b3; background: transparent; border: 1px solid rgba(255,180,110,0.55); border-radius: 6px; padding: 8px 20px;
  }
  #continue-btn.active { display: inline-block; }

  /* Title backdrop: a live 2D skyline/sun scene painted under the title copy. */
  #title-backdrop {
    position: absolute; left: 0; right: 0; bottom: 0; width: 100%; height: 42%;
    pointer-events: none; z-index: 0; opacity: 0.85;
  }
  #overlay > *:not(#title-backdrop) { position: relative; z-index: 1; }
  #overlay > #title-credits { position: absolute; }

  /* Title tabs: settings, controls, shortcuts, accessibility */
  #front-tabs { display: flex; gap: 4px; margin-top: 22px; }
  .front-tab {
    cursor: pointer; pointer-events: auto; font-size: 11px; font-weight: 800; letter-spacing: 1.8px; text-transform: uppercase;
    color: #d8cee6; background: rgba(20,14,32,0.66); border: 1px solid rgba(255,180,110,0.25);
    border-radius: 5px 5px 0 0; padding: 7px 14px;
  }
  .front-tab[aria-selected="true"] { color: #160e20; background: linear-gradient(90deg, #ff9947, #ffcf5c); border-color: transparent; }
  .front-tab:focus-visible, #play-btn:focus-visible, #continue-btn:focus-visible { outline: 2px solid #5ef0f0; outline-offset: 2px; }
  #front-panels {
    width: min(640px, calc(100vw - 40px)); min-height: 178px; max-height: 40vh; overflow: auto;
    background: rgba(16,12,28,0.82); border: 1px solid rgba(255,180,110,0.25); border-radius: 0 6px 6px 6px;
    padding: 14px 18px; font-size: 12px; color: #e6dcf0; pointer-events: auto;
  }
  .front-panel { display: none; }
  .front-panel.active { display: block; }
  #settings-form { display: grid; grid-template-columns: 150px 1fr 54px; gap: 9px 12px; align-items: center; }
  #settings-form label { font-weight: 700; letter-spacing: 1px; text-transform: uppercase; font-size: 11px; color: #ffd9b3; }
  #settings-form select, #settings-form input[type="range"] { width: 100%; accent-color: #ff9947; }
  #settings-form select {
    background: #1d1530; color: #fff6ec; border: 1px solid rgba(255,180,110,0.4); border-radius: 4px; padding: 3px 6px; font-size: 12px;
  }
  #settings-form output { font-variant-numeric: tabular-nums; color: #5ef0f0; font-weight: 800; text-align: right; }
  #settings-actions { grid-column: 1 / -1; display: flex; gap: 8px; justify-content: flex-end; margin-top: 4px; }
  .mini-btn {
    cursor: pointer; font-size: 10px; font-weight: 800; letter-spacing: 1.6px; text-transform: uppercase;
    background: transparent; color: #ffd9b3; border: 1px solid rgba(255,180,110,0.5); border-radius: 4px; padding: 5px 12px;
  }
  .ref-table { width: 100%; border-collapse: collapse; }
  .ref-table th { text-align: left; font-size: 10px; letter-spacing: 1.8px; text-transform: uppercase; color: #ff9c54; padding: 0 6px 6px; }
  .ref-table td { padding: 4px 6px; border-top: 1px solid rgba(255,255,255,0.07); }
  .ref-table td:first-child { color: #fff6ec; font-weight: 700; }
  kbd {
    display: inline-block; min-width: 20px; text-align: center; font-family: inherit; font-size: 11px; font-weight: 800;
    color: #160e20; background: #ffd9b3; border-radius: 3px; padding: 1px 5px; box-shadow: 0 2px 0 #b9875e; margin-right: 2px;
  }
  #a11y-note p { margin: 0 0 8px; line-height: 1.5; }

  /* HUD extras: notification stack, cash delta, weapon wheel, speedo dial, wanted ring, mission log, stats */
  #notify-stack {
    position: absolute; top: 74px; left: 24px; width: 280px;
    display: flex; flex-direction: column; gap: 6px;
  }
  .notify {
    font-size: 12px; font-weight: 700; letter-spacing: 0.5px; color: #fff6ec;
    background: linear-gradient(90deg, rgba(18,14,32,0.9), rgba(18,14,32,0.6));
    border-left: 3px solid #5ef0f0; border-radius: 4px; padding: 7px 10px;
    transition: opacity 0.4s ease, transform 0.4s ease;
  }
  .notify.warn { border-left-color: #ff4558; }
  .notify.cash { border-left-color: #5ef2a5; }
  .notify.fading { opacity: 0; transform: translateX(-16px); }
  #cash-delta {
    font-size: 15px; font-weight: 800; color: #5ef2a5; text-shadow: 0 2px 6px rgba(0,0,0,0.85);
    opacity: 0; transition: opacity 0.3s ease; font-variant-numeric: tabular-nums;
  }
  #cash-delta.active { opacity: 1; }
  #cash-delta.neg { color: #ff6a7a; }
  #wanted-ring { position: absolute; top: 2px; left: -34px; width: 28px; height: 28px; display: none; }
  #wanted-ring.active { display: block; }
  #wanted-row { position: relative; }
  #speedo-dial { width: 120px; height: 72px; display: block; margin-bottom: -6px; }
  #weapon-wheel {
    position: absolute; top: 50%; left: 50%; width: 260px; height: 260px; transform: translate(-50%, -50%);
    border-radius: 50%; display: none;
    background: radial-gradient(circle, rgba(14,10,24,0.2) 28%, rgba(14,10,24,0.82) 30%, rgba(14,10,24,0.82) 70%, rgba(14,10,24,0) 71%);
  }
  #weapon-wheel.active { display: block; }
  .wheel-slot {
    position: absolute; width: 86px; margin-left: -43px; margin-top: -14px; text-align: center;
    font-size: 11px; font-weight: 800; letter-spacing: 1.2px; color: rgba(255,240,224,0.6);
  }
  .wheel-slot.selected { color: #ffcf5c; text-shadow: 0 0 10px rgba(255,170,60,0.8); }
  .wheel-slot.locked { color: rgba(255,255,255,0.22); }
  #mission-log {
    position: absolute; top: 74px; right: 24px; margin-top: 150px; width: 220px; display: none;
    background: rgba(14,12,24,0.78); border: 1px solid rgba(255,180,110,0.22); border-radius: 6px; padding: 8px 10px;
    font-size: 11px; line-height: 1.6;
  }
  #mission-log.active { display: block; }
  #mission-log h3 { margin: 0 0 4px; font-size: 10px; letter-spacing: 2px; color: #ff9c54; }
  #mission-log .done { color: #5ef2a5; }
  #mission-log .failed { color: #ff6a7a; }
  #mission-log .pending { color: rgba(255,240,224,0.5); }
  #stats-panel {
    position: absolute; bottom: 8px; left: 50%; transform: translateX(-50%); display: none;
    font: 11px/1.4 ui-monospace, Menlo, Consolas, monospace; color: #c9f7ff;
    background: rgba(8,10,18,0.72); border-radius: 4px; padding: 4px 10px; white-space: pre;
  }
  #stats-panel.active { display: block; }
  #pause-hint { font-size: 11px; letter-spacing: 2px; color: rgba(255,230,210,0.66); margin-top: 6px; display: none; }
  body.reduce-motion #title-backdrop { display: none; }
  body.reduce-motion .notify, body.reduce-motion #hud { transition: none; }
  body.high-contrast #hud { filter: contrast(1.25) saturate(1.15); }
  body.large-hud #hud { zoom: 1.18; }
  @media (max-width: 760px) {
    #front-panels { font-size: 11px; }
    #settings-form { grid-template-columns: 110px 1fr 44px; }
    #notify-stack, #mission-log { display: none !important; }
  }
</style>
</head>
<body>
<div id="game-wrap">
  <canvas id="viewport"></canvas>
