    <div id="mission-log" aria-label="Mission log"><h3>STORY LOG</h3><div id="mission-log-list"></div></div>
    <div id="weapon-wheel" aria-label="Weapon wheel">
      <div class="wheel-slot" data-weapon="fists" style="left:50%;top:16%">FISTS</div>
