    <div id="loading-step">Loading modules</div>
    <ul id="loading-modules">
      <li data-step="modules">Modules</li><li data-step="textures">Textures</li><li data-step="render">Renderer</li><li data-step="city">City</li>
      <li data-step="vehicles">Traffic</li><li data-step="peds">Pedestrians</li><li data-step="player">Player</li><li data-step="police">Police</li>
      <li data-step="combat">Combat</li><li data-step="missions">Missions</li><li data-step="hud">HUD</li><li data-step="ready">Ready</li>
    </ul>
