    <h1 id="title-logo">VICE MERIDIAN</h1>
    <p id="title-sub">Roam Marisol Bay as Rico Vela. Boost custom cruisers, outrun the Meridian PD, run jobs for fixer Tessa Marlow, and settle scores along the docks.</p>
    <button id="play-btn" type="button">PLAY VICE MERIDIAN</button>
    <button id="continue-btn" type="button">CONTINUE SAVED GAME</button>
    <div id="pause-hint">P · ESC · ENTER TO RESUME</div>
    <div id="front-tabs" role="tablist">
      <button class="front-tab" role="tab" type="button" aria-selected="true" data-panel="panel-settings">Settings</button>
      <button class="front-tab" role="tab" type="button" aria-selected="false" data-panel="panel-controls">Controls</button>
      <button class="front-tab" role="tab" type="button" aria-selected="false" data-panel="panel-shortcuts">Shortcuts</button>
      <button class="front-tab" role="tab" type="button" aria-selected="false" data-panel="panel-a11y">Accessibility</button>
