    <div id="front-panels">
      <section id="panel-settings" class="front-panel active" role="tabpanel">
        <form id="settings-form" onsubmit="return false">
          <label for="set-quality">Quality preset</label>
          <select id="set-quality" name="quality">
            <option value="auto">Auto (frame guard)</option><option value="low">Low</option>
            <option value="medium">Medium</option><option value="high">High</option>
          </select><output id="out-quality">AUTO</output>
          <label for="set-fov">Field of view</label>
          <input id="set-fov" name="fov" type="range" min="50" max="95" step="1"><output id="out-fov">62</output>
