          <label for="set-invert">Invert Y axis</label>
          <select id="set-invert" name="invertY"><option value="0">Off</option><option value="1">On</option></select><output id="out-invert">OFF</output>
          <label for="set-volume">Master volume</label>
          <input id="set-volume" name="volume" type="range" min="0" max="100" step="1"><output id="out-volume">80</output>
