            <option value="easy">Easy — slower heat, weaker shots</option><option value="normal">Normal</option>
            <option value="hard">Hard — faster heat, sharper cops</option>
          </select><output id="out-difficulty">NORMAL</output>
          <div id="settings-actions">
            <button class="mini-btn" id="settings-reset" type="button">Reset defaults</button>
          </div>
        </form>
