</div>
<script>
// Front end for VICE MERIDIAN: settings persistence, menu tabs, the loading progress bar and the
// animated title backdrop. Plain script (not a module) so it runs before the game modules load and
// main.js can read window.VMFront the moment it boots.
(function () {
  'use strict';
  var SETTINGS_KEY = 'vice-meridian-settings-v1';
  var DEFAULTS = {
    quality: 'auto', fov: 62, sensitivity: 1, invertY: false, volume: 80, difficulty: 'normal',
    reduceMotion: false, highContrast: false, largeHud: false,
  };
  var QUALITY = ['auto', 'low', 'medium', 'high'];
  var DIFFICULTY = ['easy', 'normal', 'hard'];
  var params = new URLSearchParams(window.location.search);
  var shotMode = params.has('shot');

  function clampNum(v, lo, hi, fallback) {
    var n = Number(v);
    if (!isFinite(n)) return fallback;
    return n < lo ? lo : n > hi ? hi : n;
  }

  // Validate every field so a hand-edited or stale localStorage entry can never break the game.
  function sanitize(raw) {
    var s = {};
    raw = raw && typeof raw === 'object' ? raw : {};
    s.quality = QUALITY.indexOf(raw.quality) >= 0 ? raw.quality : DEFAULTS.quality;
    s.fov = Math.round(clampNum(raw.fov, 50, 95, DEFAULTS.fov));
    s.sensitivity = Math.round(clampNum(raw.sensitivity, 0.2, 3, DEFAULTS.sensitivity) * 100) / 100;
    s.invertY = raw.invertY === true || raw.invertY === '1' || raw.invertY === 1;
    s.volume = Math.round(clampNum(raw.volume, 0, 100, DEFAULTS.volume));
    s.difficulty = DIFFICULTY.indexOf(raw.difficulty) >= 0 ? raw.difficulty : DEFAULTS.difficulty;
    s.reduceMotion = raw.reduceMotion === true;
    s.highContrast = raw.highContrast === true;
    s.largeHud = raw.largeHud === true;
    return s;
  }

  function loadSettings() {
    // Shots must never depend on what a previous session stored.
    if (shotMode) return sanitize(DEFAULTS);
    try {
      var raw = window.localStorage.getItem(SETTINGS_KEY);
      return sanitize(raw ? JSON.parse(raw) : DEFAULTS);
    } catch (e) {
      return sanitize(DEFAULTS);
    }
  }

  var settings = loadSettings();
  var listeners = [];

  function persist() {
    if (shotMode) return;
    try { window.localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings)); } catch (e) { /* storage disabled: keep the in-memory copy */ }
  }

  function applyBodyClasses() {
    document.body.classList.toggle('reduce-motion', settings.reduceMotion);
    document.body.classList.toggle('high-contrast', settings.highContrast);
    document.body.classList.toggle('large-hud', settings.largeHud);
  }

  function emit() {
    applyBodyClasses();
    for (var i = 0; i < listeners.length; i++) {
      try { listeners[i](settings); } catch (e) { console.error(e); }
    }
  }

  function update(patch) {
    var next = {};
    for (var k in settings) next[k] = settings[k];
    for (var p in patch) next[p] = patch[p];
    settings = sanitize(next);
    persist();
    syncForm();
    emit();
  }

  function byId(id) { return document.getElementById(id); }

  function syncForm() {
    var q = byId('set-quality'); if (!q) return;
    q.value = settings.quality; byId('out-quality').textContent = settings.quality.toUpperCase();
    byId('set-fov').value = settings.fov; byId('out-fov').textContent = String(settings.fov);
    byId('set-sens').value = settings.sensitivity; byId('out-sens').textContent = settings.sensitivity.toFixed(2);
    byId('set-invert').value = settings.invertY ? '1' : '0'; byId('out-invert').textContent = settings.invertY ? 'ON' : 'OFF';
    byId('set-volume').value = settings.volume; byId('out-volume').textContent = String(settings.volume);
    byId('set-difficulty').value = settings.difficulty; byId('out-difficulty').textContent = settings.difficulty.toUpperCase();
    byId('set-reduce-motion').checked = settings.reduceMotion;
    byId('set-contrast').checked = settings.highContrast;
    byId('set-large-hud').checked = settings.largeHud;
  }

  function wireForm() {
    var bind = function (id, evt, fn) { var el = byId(id); if (el) el.addEventListener(evt, fn); };
    bind('set-quality', 'change', function (e) { update({ quality: e.target.value }); });
    bind('set-fov', 'input', function (e) { update({ fov: e.target.value }); });
    bind('set-sens', 'input', function (e) { update({ sensitivity: e.target.value }); });
    bind('set-invert', 'change', function (e) { update({ invertY: e.target.value === '1' }); });
    bind('set-volume', 'input', function (e) { update({ volume: e.target.value }); });
    bind('set-difficulty', 'change', function (e) { update({ difficulty: e.target.value }); });
    bind('set-reduce-motion', 'change', function (e) { update({ reduceMotion: e.target.checked }); });
    bind('set-contrast', 'change', function (e) { update({ highContrast: e.target.checked }); });
    bind('set-large-hud', 'change', function (e) { update({ largeHud: e.target.checked }); });
    bind('settings-reset', 'click', function () { update(DEFAULTS); });
    // Keep menu clicks from bubbling to the overlay's "click anywhere to play" handler.
    var panels = byId('front-panels'); if (panels) panels.addEventListener('click', function (e) { e.stopPropagation(); });
    var tabs = document.querySelectorAll('.front-tab');
    for (var i = 0; i < tabs.length; i++) {
      tabs[i].addEventListener('click', function (e) {
        e.stopPropagation();
        selectTab(e.currentTarget);
      });
      tabs[i].addEventListener('keydown', function (e) {
        if (e.key !== 'ArrowRight' && e.key !== 'ArrowLeft') return;
        var all = Array.prototype.slice.call(document.querySelectorAll('.front-tab'));
        var idx = all.indexOf(e.currentTarget);
        var next = all[(idx + (e.key === 'ArrowRight' ? 1 : all.length - 1)) % all.length];
        selectTab(next); next.focus(); e.preventDefault();
      });
    }
  }

  function selectTab(tab) {
    var tabs = document.querySelectorAll('.front-tab');
    for (var i = 0; i < tabs.length; i++) {
      var on = tabs[i] === tab;
      tabs[i].setAttribute('aria-selected', on ? 'true' : 'false');
      var panel = byId(tabs[i].getAttribute('data-panel'));
      if (panel) panel.classList.toggle('active', on);
    }
  }

  // Loading progress. main.js reports each subsystem as it is constructed, in module order; the
  // bar is determinate and the step list ticks off what is done.
  var STEPS = ['modules', 'textures', 'render', 'city', 'vehicles', 'peds', 'player', 'police', 'combat', 'missions', 'hud', 'ready'];
  var LABELS = {
    modules: 'Loading modules', textures: 'Painting textures', render: 'Lighting the bay', city: 'Generating Marisol Bay',
    vehicles: 'Fuelling traffic', peds: 'Filling the sidewalks', player: 'Waking Rico', police: 'Dispatching Meridian PD',
    combat: 'Loading the armoury', missions: 'Briefing Tessa', hud: 'Drawing the HUD', ready: 'Ready',
  };
  function progress(step) {
    var idx = STEPS.indexOf(step);
    if (idx < 0) return;
    var pct = Math.round(((idx + 1) / STEPS.length) * 100);
    var fill = byId('loading-fill'); if (fill) fill.style.width = pct + '%';
    var pctEl = byId('loading-pct'); if (pctEl) pctEl.textContent = pct + '%';
    var stepEl = byId('loading-step'); if (stepEl) stepEl.textContent = LABELS[step];
    var root = byId('loading'); if (root) root.setAttribute('aria-valuenow', String(pct));
    var items = document.querySelectorAll('#loading-modules li');
    for (var i = 0; i < items.length; i++) {
      var si = STEPS.indexOf(items[i].getAttribute('data-step'));
      items[i].classList.toggle('done', si <= idx);
      items[i].classList.toggle('active', si === idx + 1);
    }
  }

  // Animated title backdrop: a banded synthwave sun sinking behind a layered skyline, with palms
  // and a scrolling road grid. Building heights come from an integer hash, so the skyline is the
  // same every visit; only the animation phase advances.
  function hash(n) {
    n = Math.imul(n ^ 0x27d4eb2d, 0x165667b1);
    n = Math.imul(n ^ (n >>> 15), 0x2c1b3c6d);
    return ((n ^ (n >>> 13)) >>> 0) / 4294967296;
  }
  function startBackdrop() {
    var canvas = byId('title-backdrop');
    var overlay = byId('overlay');
    if (!canvas || shotMode) return;
    var ctx = canvas.getContext('2d');
    var t0 = performance.now();
    function draw(now) {
      requestAnimationFrame(draw);
      if (overlay.classList.contains('hidden') || settings.reduceMotion) return;
      var w = canvas.clientWidth | 0, h = canvas.clientHeight | 0;
      if (w < 2 || h < 2) return;
      if (canvas.width !== w || canvas.height !== h) { canvas.width = w; canvas.height = h; }
      var t = (now - t0) / 1000;
      ctx.clearRect(0, 0, w, h);
      var horizon = h * 0.62;
      // Sun with horizontal cut bands that slide downward.
      var sunR = Math.min(w, h) * 0.42;
      var sx = w * 0.5, sy = horizon - sunR * 0.18;
      var g = ctx.createLinearGradient(0, sy - sunR, 0, sy + sunR);
      g.addColorStop(0, 'rgba(255,236,150,0.9)'); g.addColorStop(0.55, 'rgba(255,128,80,0.85)'); g.addColorStop(1, 'rgba(255,60,120,0.8)');
      ctx.save();
      ctx.beginPath(); ctx.arc(sx, sy, sunR, Math.PI, 0); ctx.closePath(); ctx.clip();
      ctx.fillStyle = g; ctx.fillRect(sx - sunR, sy - sunR, sunR * 2, sunR);
      ctx.globalCompositeOperation = 'destination-out';
      for (var b = 0; b < 7; b++) {
        var by = sy - sunR * 0.5 + ((b * 0.09 + t * 0.03) % 0.6) * sunR;
        ctx.fillRect(sx - sunR, by, sunR * 2, 2 + b * 0.9);
      }
      ctx.restore();
      // Two skyline layers; the near one has lit windows that blink on a slow hash cycle.
      for (var layer = 0; layer < 2; layer++) {
        var speed = 6 + layer * 10;
        var scroll = (t * speed) % 64;
        var colBase = Math.floor((t * speed) / 64) * 2;
