    if (a === b || a === undefined || b === undefined) return;
    if (adj[a].some((e) => e.to === b)) return;
    const cost = Math.hypot(nodes[a].x - nodes[b].x, nodes[a].z - nodes[b].z);
    adj[a].push({ to: b, cost });
    adj[b].push({ to: a, cost });
